tProperty("heading").GetSingle());var rotation=root.TryGetProperty("rotateX",out var rx)&&root.TryGetProperty("rotateY",out var ry)&&root.TryGetProperty("rotateZ",out var rz)?new EqRotation(rx.GetSingle(),ry.GetSingle(),rz.GetSingle()):zone.Get(id).Rotation;_history.Execute(new TransformCommand(zone,id,pos,root.GetProperty("scale").GetSingle(),rotation));StatusText.Text=$"Transformed {before.Name}";ShowInspector(zone.Get(id));return;}if(type!="select")return;_selectedId=id;ShowInspector(zone.Get(id));}catch(Exception ex){StatusText.Text=$"Viewport message failed: {ex.Message}";}}
 void ShowInspector(ZoneEntity entity){InspectorPanel.Children.Clear();InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=$"{entity.Kind}: {entity.Name}"});InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=$"X {entity.Position.X:0.00}  Y {entity.Position.Y:0.00}  Z {entity.Position.Z:0.00}  H {entity.Position.Heading:0.00}  Scale {entity.Scale:0.000}"});if(entity.Rotation is EqRotation rot)InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=$"Rotation X {rot.X:0.00}  Y {rot.Y:0.00}  Z {rot.Z:0.00}"});if(entity.ServerId is long sid)InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=$"EQEmu ID {sid}"});if(!string.IsNullOrWhiteSpace(entity.ClientAsset))InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=$"Native asset: {entity.ClientAsset}",TextWrapping=TextWrapping.Wrap});var detail=entity.Data switch{SpawnEntityData s=>$"Spawn group {s.SpawnGroupId} | Respawn {s.RespawnTime}s | Variance {s.Variance} | Grid {s.PathGrid} | Version {s.Version} | Idle path {s.PathWhenZoneIdle} | Condition {s.Condition}={s.ConditionValue} | Animation {s.Animation} | Expansions {s.MinExpansion}..{s.MaxExpansion} | Flags +[{s.ContentFlags}] -[{s.ContentFlagsDisabled}] | Group {s.GroupName} limit {s.SpawnLimit} dist {s.GroupDistance:0.00} bounds X {s.GroupMinX:0.00}..{s.GroupMaxX:0.00} Y {s.GroupMinY:0.00}..{s.GroupMaxY:0.00} delay {s.GroupMinDelay}..{s.GroupDelay} despawn {s.Despawn}/{s.DespawnTimer}s waypoints {s.WaypointSpawns}",NpcEntityData n=>$"NPC type {n.NpcTypeId} | Group {n.SpawnGroupId} | Chance {n.Chance}% | Race {n.Race} | Gender {n.Gender} | Model {n.Model} | Texture {n.Texture}/{n.HelmTexture} | Face {n.Face} | Hair {n.HairStyle}/{n.HairColor} | Eyes {n.EyeColor1}/{n.EyeColor2} | Beard {n.Beard}/{n.BeardColor} | Drakkin {n.DrakkinHeritage}/{n.DrakkinTattoo}/{n.DrakkinDetails} | Armor {n.ArmTexture},{n.BracerTexture},{n.HandTexture},{n.LegTexture},{n.FeetTexture} | Weapons {n.PrimaryWeaponTexture}/{n.SecondaryWeaponTexture} | Light {n.Light} | Spawn filter {n.SpawnConditionValueFilter} time {n.SpawnMinTime}..{n.SpawnMaxTime} expansions {n.SpawnMinExpansion}..{n.SpawnMaxExpansion} flags +[{n.SpawnContentFlags}] -[{n.SpawnContentFlagsDisabled}]",WaypointEntityData w=>$"Waypoint grid {w.GridId} #{w.Number} | pause {w.Pause}s center {w.CenterPoint} | wander {w.WanderType} pause type {w.PauseType}",GroundSpawnEntityData g=>$"Ground spawn item {g.ItemId} max {g.MaxAllowed} | bounds X {g.MinX:0.00}..{g.MaxX:0.00} Y {g.MinY:0.00}..{g.MaxY:0.00} Z {g.MaxZ:0.00} | respawn {g.RespawnTimer}s fixZ {g.FixZ} | v{g.Version} expansions {g.MinExpansion}..{g.MaxExpansion} | flags +[{g.ContentFlags}] -[{g.ContentFlagsDisabled}] | {g.Comment}",ObjectEntityData o=>$"DB object v{o.Version} | Item {o.ItemId} charges {o.Charges} | Type {o.Type} icon {o.Icon} | size% {o.SizePercentage:0.00} native {o.NativeSize:0.00} | unknown {o.Unknown24}/{o.Unknown60}/{o.Unknown64}/{o.Unknown68}/{o.Unknown72}/{o.Unknown76}/{o.Unknown84} | solid {o.SolidType} incline {o.Incline} tilt {o.TiltX:0.00}/{o.TiltY:0.00} | expansions {o.MinExpansion}..{o.MaxExpansion} | flags +[{o.ContentFlags}] -[{o.ContentFlagsDisabled}] | display {o.DisplayName} | contents {o.Contents?.Count??0}"+((o.Contents?.Count??0)>0?$" [{string.Join("; ",o.Contents!.Take(8).Select(x=>$"bag{x.BagIndex}:item{x.ItemId}x{x.Charges}"))}]":""),EqgLightEffectEntityData e=>$"Sage V4 LightFX | alt {e.AltName} unknown {e.Unknown}/{e.Unknown1:0.###} | rotation {e.RotateX:0.###},{e.RotateY:0.###},{e.RotateZ:0.###} | scale {e.ScaleX:0.###},{e.ScaleY:0.###},{e.ScaleZ:0.###} | source parser preserves this record; pinned Sage exporter does not consume it",EcoLayerEntityData e=>$"ECO {e.LayerKind} {e.EcoName}/{e.LayerName} | native {e.NativeReference} texture layer {e.TextureLayer} | density {e.Density:0.###} iterations {e.Iterations} | scale {e.MinScale:0.###}..{e.MaxScale:0.###} alpha {e.MinAlpha:0.###} | height {e.MinHeight:0.###}..{e.MaxHeight:0.###} tol {e.HeightTolerance:0.###} | slope {e.MinSlope:0.###}..{e.MaxSlope:0.###} tol {e.SlopeTolerance:0.###}",ActorEntityData a=>$"Actor radius {a.BoundingRadius:0.00}"+(string.IsNullOrWhiteSpace(a.SoundName)?"":$" | Sound {a.SoundName}")+(a.VertexColorReference is int vc?$" | Vertex color ref {vc}":"")+(string.IsNullOrWhiteSpace(a.UserData)?"":$" | User data {a.UserData}"),DoorEntityData d=>$"Door ID {d.DoorId} | Open type {d.OpenType} | Version {d.Version} | Lockpick {d.Lockpick} | Key {d.KeyItem} | Trigger {d.TriggerDoor}/{d.TriggerType} | Open {d.DoorIsOpen} | Dest {d.DestZone}#{d.DestInstance} {d.DestX:0.00},{d.DestY:0.00},{d.DestZ:0.00} h {d.DestHeading:0.00} | Invert {d.InvertState} | Incline {d.Incline}",LightEntityData l=>$"Light radius {l.Radius:0.00} | Frames {l.Frames.Count} | Current {l.CurrentFrame} | Sleep {l.Sleep}"+(l.GlobalAmbient?" | Global ambient":""),RegionEntityData r=>$"Region {string.Join(", ",r.Semantics)}"+(r.ZoneLineReference is int rr?$" | zoneline ref {rr}":r.TargetZoneIndex is int zi?$" | zone {zi} target {r.TargetX},{r.TargetY},{r.TargetZ} rot {r.TargetRotation}":"")+(r.ExtentX!=0||r.ExtentY!=0||r.ExtentZ!=0?$" | extents {r.ExtentX:0.00},{r.ExtentY:0.00},{r.ExtentZ:0.00} flags {r.SourceFlag1}/{r.SourceFlag2} source {r.SourceName}":""),ZonePointEntityData p=>$"Zone point {p.Number} v{p.Version} -> zone {p.TargetZoneId} instance {p.TargetInstance} | target {p.TargetX:0.00}, {p.TargetY:0.00}, {p.TargetZ:0.00} h {p.TargetHeading:0.00} | zoneinst {p.ZoneInstance} | buffer {p.Buffer:0.00} | client mask 0x{p.ClientVersionMask:X8} | expansions {p.MinExpansion}..{p.MaxExpansion} | virtual {p.IsVirtual} {p.Width}x{p.Height} | flags +[{p.ContentFlags}] -[{p.ContentFlagsDisabled}]",_=>null};if(detail is not null)InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=detail,TextWrapping=TextWrapping.Wrap});StatusText.Text=$"Selected {entity.Name}";_ = RenderModelViewerAsync(entity);}
 void PopulateAssetViewers(CompleteZone zone){ObjectList.Items.Clear();foreach(var e in zone.Entities.Where(x=>x.Kind is ZoneEntityKind.StaticObject or ZoneEntityKind.AnimatedObject).OrderBy(x=>x.Name))ObjectList.Items.Add(new System.Windows.Controls.ListBoxItem{Content=e.Name,Tag=e.Id});TextureList.Items.Clear();if(_client is not null)foreach(var t in _client.TextureFiles.Keys.OrderBy(x=>x))TextureList.Items.Add(t);MaterialList.Items.Clear();if(_client is not null)foreach(var m in _client.RenderMeshes.Values.SelectMany(x=>x.Primitives).Select(x=>x.Material?.Name).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x))MaterialList.Items.Add(m);PopulateActiveZoneAssetTree(zone);}
 void PopulateActiveZoneAssetTree(CompleteZone zone){AssetTree.Items.Clear();var filter=AssetSearchBox.Text?.Trim()??"";var root=new System.Windows.Controls.TreeViewItem{Header=zone.ShortName,IsExpanded=true};foreach(var group in new[]{(ZoneEntityKind.WorldGeometry,"World Geometry"),(ZoneEntityKind.StaticObject,"Objects"),(ZoneEntityKind.AnimatedObject,"Animated Objects"),(ZoneEntityKind.Light,"Lights"),(ZoneEntityKind.Region,"Regions"),(ZoneEntityKind.Door,"Doors"),(ZoneEntityKind.Npc,"NPCs"),(ZoneEntityKind.Spawn,"Spawns"),(ZoneEntityKind.GroundSpawn,"Ground Spawns"),(ZoneEntityKind.ZonePoint,"Zone Points")}){var all=zone.Entities.Where(x=>x.Kind==group.Item1).ToArray();var shown=string.IsNullOrWhiteSpace(filter)?all:all.Where(x=>x.Name.Contains(filter,StringComparison.OrdinalIgnoreCase)||group.Item2.Contains(filter,StringComparison.OrdinalIgnoreCase)).ToArray();if(shown.Length==0&&!string.IsNullOrWhiteSpace(filter))continue;var branch=new System.Windows.Controls.TreeViewItem{Header=$"{group.Item2} ({all.Length})",IsExpanded=!string.IsNullOrWhiteSpace(filter)};foreach(var e in shown.OrderBy(x=>x.Name)){var item=new System.Windows.Controls.TreeViewItem{Header=e.Name,Tag=e.Id};item.Selected+=(_,args)=>{if(_session?.ActiveZone is not{} active||!active.Contains(e.Id))return;_selectedId=e.Id;ShowInspector(active.Get(e.Id));_ = ScriptAsync($"window.ddvwf?.selectId?.('{e.Id}')");args.Handled=true;};branch.Items.Add(item);}root.Items.Add(branch);}AssetTree.Items.Add(root);}
 void AssetSearchBox_TextChanged(object sender,System.Windows.Controls.TextChangedEventArgs e){if(_session?.ActiveZone is{} zone)PopulateActiveZoneAssetTree(zone);}
 async void ObjectList_SelectionChanged(object sender,System.Windows.Controls.SelectionChangedEventArgs e){if(ObjectList.SelectedItem is not System.Windows.Controls.ListBoxItem item||item.Tag is not Guid id||_session?.ActiveZone is not{} zone||!zone.Contains(id))return;_selectedId=id;ShowInspector(zone.Get(id));await ScriptAsync($"window.ddvwf?.selectId?.('{id}')");}
 async Task RenderModelViewerAsync(ZoneEntity entity){try{if(_client is null||ModelViewer.CoreWebView2 is null)return;if(entity.ClientAsset is null||!_client.RenderMeshes.ContainsKey(entity.ClientAsset)){_modelViewerAsset=null;await ModelViewer.CoreWebView2.ExecuteScriptAsync("window.ddvwf?.loadScene?.('{\\\"zone\\\":\\\"viewer\\\",\\\"meshes\\\":[],\\\"markers\\\":[],\\\"textures\\\":{}}')");StatusText.Text=$"Model Viewer: no resolved Sage render asset for {entity.Name}";return;}_modelViewerAsset=entity.ClientAsset;var z=new CompleteZone{ShortName="viewer"};z.Add(entity with{Position=new EqPosition(0,0,0,0),Rotation=new EqRotation(0,0,0),Scale=1f});var payload=BabylonSceneSerializer.Serialize(z,_client.RenderMeshes,_client.TextureFiles);await ModelViewer.CoreWebView2.ExecuteScriptAsync($"window.ddvwf.loadScene({System.Text.Json.JsonSerializer.Serialize(payload)});window.ddvwf.selectId('{entity.Id}');");if(_settings.ModelCameras.TryGetValue(entity.ClientAsset,out var camera)){var cameraJson=System.Text.Json.JsonSerializer.Serialize(new{x=camera.X,y=camera.Y,z=camera.Z,yaw=camera.Yaw,pitch=camera.Pitch,speed=camera.Speed});await ModelViewer.CoreWebView2.ExecuteScriptAsync($"window.ddvwf.setCamera({cameraJson})");}else await ModelViewer.CoreWebView2.ExecuteScriptAsync("window.ddvwf.focus();");}catch(Exception ex){StatusText.Text=$"Model Viewer failed: {ex.Message}";}}
  Task PersistAsync()=>_workspace.SaveAsync(_settings);
 async void ChooseEqRoot_Click(object sender,RoutedEventArgs e){var dialog=new Microsoft.Win32.OpenFolderDialog{Title="Select EverQuest client directory",Multiselect=false};if(dialog.ShowDialog(this)!=true)return;_settings=_settings with{EqRoot=dialog.FolderName,LastZone=null};DiscoverZones();ZoneText.Text="Choose a zone from EQ Asset Browser";StatusText.Text=dialog.FolderName;await PersistAsync();}
 async void Compass_Click(object sender,RoutedEventArgs e){_compassVisible=true;if(_settings.Windows.TryGetValue("Compass",out var w)){_compassLeft=w.Left;_compassTop=w.Top;_compassWidth=Math.Max(180,w.Width);_compassHeight=Math.Max(180,w.Height);}var palette=System.Text.Json.JsonSerializer.Serialize(_settings.Theme.Palette);await ScriptAsync($"window.ddvwf?.setCompassState?.({{left:{_compassLeft.ToString(System.Globalization.CultureInfo.InvariantCulture)},top:{_compassTop.ToString(System.Globalization.CultureInfo.InvariantCulture)},width:{_compassWidth.ToString(System.Globalization.CultureInfo.InvariantCulture)},height:{_compassHeight.ToString(System.Globalization.CultureInfo.InvariantCulture)},visible:true,palette:{palette}}});window.ddvwf?.setCompassHeading?.({_settings.Camera.Yaw.ToString(System.Globalization.CultureInfo.InvariantCulture)})");}
 async void ThemeEditor_Click(object sender,RoutedEventArgs e){var original=_settings.Theme;var w=new ThemeEditorWindow(original,ApplyTheme){Owner=this};if(w.ShowDialog()==true){_settings=_settings with{Theme=w.Settings};ApplyTheme(w.Settings);await PersistAsync();}else ApplyTheme(original);}
 async void Shortcuts_Click(object sender,RoutedEventArgs e){var w=new ShortcutEditorWindow(_settings.Shortcuts,_settings.Theme,changed=>{_settings=_settings with{Shortcuts=new Dictionary<string,string>(changed,StringComparer.OrdinalIgnoreCase)};_ = PersistAsync();StatusText.Text="Shortcuts saved";}){Owner=this};w.ShowDialog();}
 void ApplyTheme(ThemeSettings theme){try{var palette=ThemeSettings.DefaultPalette();foreach(var p in theme.Palette)palette[p.Key]=p.Value;foreach(var p in palette)Resources[p.Key]=new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(p.Value));Foreground=(System.Windows.Media.Brush)Resources["TextBrush"];Background=(System.Windows.Media.Brush)Resources["WindowBackgroundBrush"];SceneTree.Foreground=(System.Windows.Media.Brush)Resources["SceneZoneTextBrush"];SceneTree.Background=(System.Windows.Media.Brush)Resources["SceneZoneBackgroundBrush"];AssetTree.Foreground=(System.Windows.Media.Brush)Resources["AssetBrowserTextBrush"];AssetTree.Background=(System.Windows.Media.Brush)Resources["AssetBrowserBackgroundBrush"];ObjectList.Foreground=(System.Windows.Media.Brush)Resources["ListTextBrush"];ObjectList.Background=(System.Windows.Media.Brush)Resources["RightPaneBackgroundBrush"];TextureList.Foreground=(System.Windows.Media.Brush)Resources["ListTextBrush"];TextureList.Background=(System.Windows.Media.Brush)Resources["RightPaneBackgroundBrush"];MaterialList.Foreground=(System.Windows.Media.Brush)Resources["ListTextBrush"];MaterialList.Background=(System.Windows.Media.Brush)Resources["RightPaneBackgroundBrush"];if(Viewport.CoreWebView2 is not null){var paletteJson=System.Text.Json.JsonSerializer.Serialize(theme.Palette);_=Viewport.CoreWebView2.ExecuteScriptAsync($"window.ddvwf?.buildCompass?.({paletteJson})");}if(Viewport.CoreWebView2 is not null)_=Viewport.CoreWebView2.ExecuteScriptAsync($"window.ddvwf?.setBackground?.({System.Text.Json.JsonSerializer.Serialize(palette["ViewportBrush"])})");if(ModelViewer.CoreWebView2 is not null)_=ModelViewer.CoreWebView2.ExecuteScriptAsync($"window.ddvwf?.setBackground?.({System.Text.Json.JsonSerializer.Serialize(palette["ModelPreviewBackgroundBrush"])})");}catch(Exception ex){StatusText.Text=$"Theme apply failed: {ex.Message}";}}
 async void ReloadZone_Click(object sender,RoutedEventArgs e){if(_session?.ActiveZone is not{} z)return;await OpenZoneAsync(z.ShortName);}
 void About_Click(object sender,RoutedEventArgs e){MessageBox.Show(this,"Dragon's Den Visual WorldForge\nComplete Zone IR integration build","DDVWF");}
 async void ServerSettings_Click(object sender,RoutedEventArgs e){var w=new ServerSettingsWindow(_settings.Server,_settings.Theme){Owner=this};DdvwfChrome.AttachPersistentGeometry(w,"server-settings");if(w.ShowDialog()!=true)return;_settings=_settings with{Server=w.Settings};await PersistAsync();StatusText.Text="EQEmu SQL settings saved. Reload the zone to apply.";}
 void OpenZone_Click(object sender,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(_settings.EqRoot)||!Directory.Exists(_settings.EqRoot)){StatusText.Text="Configure a valid EverQuest directory before opening a zone.";return;}DiscoverZones();StatusText.Text="Double-click a zone in EQ Asset Browser.";}
 async void CloseZone_Click(object sender,RoutedEventArgs e){_session?.Close();_selectedId=null;SceneTree.Items.Clear();AssetTree.Items.Clear();ObjectList.Items.Clear();TextureList.Items.Clear();MaterialList.Items.Clear();InspectorPanel.Children.Clear();ZoneText.Text="No zone loaded";await ScriptAsync("window.ddvwf?.loadScene?.('{\"zone\":\"\",\"meshes\":[],\"markers\":[],\"textures\":{}}')");if(ModelViewer.CoreWebView2 is not null)await ModelViewer.CoreWebView2.ExecuteScriptAsync("window.ddvwf?.loadScene?.('{\"zone\":\"\",\"meshes\":[],\"markers\":[],\"textures\":{}}')");StatusText.Text="Zone closed";}
 async Task ScriptAsync(string script){if(Viewport.CoreWebView2 is not null)await Viewport.CoreWebView2.ExecuteScriptAsync(script);}
 async void SelectMode_Click(object sender,RoutedEventArgs e)=>await ScriptAsync("window.ddvwf?.setMode?.('select')");
 async void MoveMode_Click(object sender,RoutedEventArgs e)=>await ScriptAsync("window.ddvwf?.setMode?.('move')");
 async void RotateMode_Click(object sender,RoutedEventArgs e)=>await ScriptAsync("window.ddvwf?.setMode?.('rotate')");
 async void ScaleMode_Click(object sender,RoutedEventArgs e)=>await ScriptAsync("window.ddvwf?.setMode?.('scale')");
 async void Focus_Click(object sender,RoutedEventArgs e)=>await ScriptAsync("window.ddvwf?.focus?.()");
 async void Delete_Click(object sender,RoutedEventArgs e){if(_selectedId is not Guid id||_session?.ActiveZone is not{} z)return;_history.Execute(new DeleteEntityCommand(z,id));await ScriptAsync($"window.ddvwf?.remove?.('{id}\')");_selectedId=null;PopulateAssetViewers(z);InspectorPanel.Children.Clear();StatusText.Text="Deleted entity";}
 async void Duplicate_Click(object sender,RoutedEventArgs e){if(_selectedId is not Guid id||_session?.ActiveZone is not{} z)return;var source=z.Get(id);if(source.ServerId is not null){StatusText.Text="Server-backed entities are not duplicated until write-back semantics are enabled.";return;}var p=source.Position;var command=new DuplicateEntityCommand(z,id,new EqPosition(p.X+2,p.Y,p.Z,p.Heading));_history.Execute(command);_selectedId=command.NewId;await RenderActiveAsync();await ScriptAsync($"window.ddvwf?.selectId?.('{command.NewId}')");ShowInspector(z.Get(command.NewId));}
 async void Stamp_Click(object sender,RoutedEventArgs e){if(_selectedId is not Guid id||_session?.ActiveZone is not{} z)return;var source=z.Get(id);if(source.ServerId is not null){StatusText.Text="Server-backed entities cannot be stamped until database write-back is enabled.";return;}var cam=_settings.Camera;var command=new DuplicateEntityCommand(z,id,new EqPosition(cam.X,cam.Y,cam.Z,source.Position.Heading));_history.Execute(command);_selectedId=command.NewId;await RenderActiveAsync();await ScriptAsync($"window.ddvwf?.selectId?.('{command.NewId}')");ShowInspector(z.Get(command.NewId));StatusText.Text=$"Stamped {source.Name} at camera position";}
 async Task RenderActiveAsync(){if(_session?.ActiveZone is not{} zone||_client is null)return;var payload=BabylonSceneSerializer.Serialize(zone,_client.RenderMeshes,_client.TextureFiles);await ScriptAsync($"window.ddvwf.loadScene({System.Text.Json.JsonSerializer.Serialize(payload)})");PopulateAssetViewers(zone);if(_selectedId is Guid id&&zone.Contains(id)){await ScriptAsync($"window.ddvwf?.selectId?.(\'{id}\')");ShowInspector(zone.Get(id));}else _selectedId=null;}
 async void Undo_Click(object sender,RoutedEventArgs e){if(_history.Undo()){await RenderActiveAsync();StatusText.Text="Undo";}}
 async void Redo_Click(object sender,RoutedEventArgs e){if(_history.Redo()){await RenderActiveAsync();StatusText.Text="Redo";}}
 void Exit_Click(object sender,RoutedEventArgs e)=>Close();
}
